@OptIn(ExperimentalJsExport::class)
@JsExport
fun loop() {
    try {
        runWithSourceMapSupport {
            PainAndGain.tick()
        }
    } catch (t: Throwable) {
        // страховка: даже если source-map-обработчик упадёт, логируем ошибку и не роняем тик
        println("loop error: ${t.message}")
        println(t.stackTraceToString())
    }
}

/**
 * Season 4 «Pain and Gain» (basic). Первая версия — до первого живого матча.
 *
 * Правила (описание арены в клиенте, 04.09.2026): у каждого игрока ЗАРАНЕЕ ВЫДАННАЯ армия из 14
 * крипов — ни спавна, ни стройки, ни энергии, ни замены погибшим. По карте семь нейтральных
 * [ScoreFlag]: крип захватывает флаг, ВСТАВ на его клетку; захваченный флаг каждый тик приносит
 * владельцу очки и вешает глобальный дебафф на ВСЮ его армию (флаги одного типа складываются):
 *
 *  | флаг              | шт | очки/тик | эффект                      | один  | два  |
 *  |-------------------|----|----------|-----------------------------|-------|------|
 *  | Vulnerability     | 1  | 5        | входящий боевой урон        | ×1.1  | —    |
 *  | Heal reduction    | 2  | 4        | лечение                     | ×0.75 | ×0.5 |
 *  | Attack reduction  | 2  | 3        | удар ATTACK                 | ×0.8  | ×0.6 |
 *  | Ranged reduction  | 2  | 3        | выстрел RANGED_ATTACK       | ×0.8  | ×0.6 |
 *
 * Итого 25 очков/тик (MAX_SCORE_PER_TICK). 2000 тиков; побеждает больший счёт, равный — ничья;
 * досрочно — уничтожение армии противника (победа независимо от счёта) или недосягаемый отрыв.
 *
 * Оси решения, все из состояния, не из подгонки под карту:
 *  - счёт: безоружные крипы — захватчики, идут по флагам по выигрышу очков за тик хода; армия
 *    берёт флаги по пути и рейдом. Флаг берётся, только если армия С ЕГО дебаффом не слабее
 *    армии врага (маргинальная цена по Ланчестеру с эффектами обеих сторон) — или если по
 *    прогнозу счёта мы проигрываем: тогда очки важнее силы;
 *  - бой: армия одной группой; постура — ДОБИТЬ (уничтожение армии врага выигрывает матч:
 *    перевес PUSH_RATIO по мощи с эффектами), РЕЙД/ЗАЧИСТКА флага, ПОСТ у своих флагов, ОТХОД
 *    (враг сильнее в RETREAT_RATIO и рядом — армию без замены не разменивают). Внутри — локальный
 *    перевес, цена боя в запасе хода, сплочение, бегство от смертельного урона, фокус, лечение;
 *  - мощь считается по МОДИФИЦИРОВАННЫМ эффектами урону, лечению и хитам (InfluenceMap).
 */
object PainAndGain {

    // ---------- боевые константы ----------
    internal const val MELEE_KEEP_RANGE = 2
    internal const val MELEE_KITE_DISCOUNT = 0.1
    private const val MELEE_ADJACENCY_SHARE = 0.25
    /** ОТВЕРГНУТО (v195, см. inFront в planFight): мили вставал позади стрелков, когда по замеру не достаёт. Правило
     *  почти не срабатывало — прибор `back` дал 2 тика за матч, — потому что против СОМКНУТОГО блока строй раздаёт
     *  planBlock, а не planFight. И посылка неверна: в planBlock мили стоит в общей линии со стрелками НАМЕРЕННО, и
     *  рядом записан замер, который это держит, — строй «стрелки впереди, мили позади» (v37) кайтер стенда разоружал
     *  первыми. Живые числа согласны: гибнут только атакующие части (0–16 из 32), стрелковые целы (24–30 из 30), то
     *  есть тела мили работают самой дешёвой бронёй, какая у нас есть. Убирать броню, которая всё равно ничего не
     *  бьёт, — значит подставить под тот же огонь единственное, чем мы бьём. */

    /** Перевес, при котором армия идёт добивать, и порог продолжения. Порог продолжения выше единицы: прежний
     *  0.9 вместе со входом «по контакту» открывал лазейку — контакт с ОДНИМ стрелком включал ДОБИТЬ, а дальше
     *  гистерезис держал его при 0.97, и армия прошла через всю карту к вражескому углу (матч 3, t=60–96). */
    internal const val PUSH_RATIO = 1.3
    /** Наступление окупается: за окно STALL_TICKS с врага снято не меньше, чем с нас (суммы хитов живых, лечение обеих сторон
     *  внутри), иначе наступление снимается и строй собирается заново. Матч 44 (けろびー v1): к 180-му мы выигрывали
     *  16000/16000 против 12800/12800, трое его мили мертвы, и при перевесе 1.3 армия пошла в наступление — строй распущен,
     *  крипы гнались поодиночке за линией стрелков, которая отошла на 18 клеток, стреляя из трёх: 311 его выстрелов против
     *  наших 175 (68 % крип-тиков с выстрелом против 44 %), r→melee 137 по идущим первыми мили — за 60 тиков размен
     *  перевернулся, армия потеряна. Ланчестер даёт право наступать, размен говорит, окупается ли оно. */
    internal const val PUSH_EXCHANGE = 1.0
    internal const val FLEE_EDGE_MIN = 8   // = EDGE_CORNER вскрытия: бой с центром ближе восьми к краю — «у стены»
    private const val FOCUS_GUNS_SWITCH = 2
    /** Флаг перехвата — тот из не его флагов, к которому МЫ успеваем раньше (наш путь + запас ≤ его дистанция), первый в его
     *  порядке (по близости к нему), и он липкий: держится, пока он его не возьмёт. Первая форма («ближайший к его центру»)
     *  дребезжала с каждым его шагом — матч 59: армия ходила между (8,90), (31,67), (49,49) и (13,49), по 40–60 клеток, и никуда не
     *  приходила, пока он фармил 17 в тик (9359:24080). */
    private const val INTERCEPT_MARGIN = 2
    private const val PUSH_RELEASE_RATIO = 1.1

    /** Проигрывая по прогнозу счёта, армия идёт добивать при меньшем перевесе: очки — у того, кто держит больше
     *  флагов, и он же слабее (дебаффы глобальны на сторону), а отсидеться — проиграть наверняка. Не при
     *  равенстве: оценка мощи шумит на ±5%, а прогноз счёта на 41-м тике («отстаём» на пять очков, пока скаут
     *  делает последний шаг к флагу) — не повод для решающего боя (стенд army). */
    internal const val PUSH_RATIO_BEHIND = 1.1
    private const val PUSH_RELEASE_RATIO_BEHIND = 1.05

    /** Отставание, длящееся дольше стольких тиков, — уже не «скаут делает последний шаг к флагу», а пат: враг держит
     *  на флаг больше, его армия стоит, а наша при 1.01 полторы тысячи тиков ждёт перевеса 1.1 и проигрывает по
     *  очкам по единице в тик (стенд m3 army: 20252:20028 на 1992-м тике). Тогда в бой при равенстве. */
    private const val BEHIND_PATIENCE = 200
    private const val PUSH_RATIO_STALEMATE = 1.0
    /** Бесплодная охота (v20): в ДОБИТЬ без обмена уронами STALL_TICKS подряд давление, бой по контакту и «держим линию»
     *  снимаются на STALL_COOLDOWN тиков — армия идёт за флагами; любой удар в любую сторону снимает паузу. Враг россыпью
     *  (матч 19) разобрал все флаги по одному-трём крипам и держал +25 в тик, а наша армия при 1.34 стояла в ДОБИТЬ рядом
     *  с его крипами, висевшими в 4–6 клетках и отступавшими на клетку при каждом нашем шаге (равная скорость — ни одного
     *  удара за матч), и флагов не брала: ДОБИТЬ обнуляет цель. Гейт по дальности до цели («охота только вблизи») это не
     *  чинит — висящие в шести клетках «вблизи», а против армии, которая дерётся при подходе (стенд m3 army), он выключил
     *  давление вовсе, и обе армии простояли до конца. Критерий — результат, не дистанция. */
    internal const val STALL_TICKS = 20
    internal const val STALL_COOLDOWN = 300   // до чистого урона врагу или столько тиков: 60 рвали марш к флагу каждым циклом
    /** Простой — это пикет, не армия: не больше стольких вооружённых врагов в досягаемости броска, и все STALL_TICKS
     *  подряд. Матч 20: авангард армии врага вошёл в восемь клеток на 64-м тике, окно «20 тиков без урона» считалось с
     *  начала матча — простой сработал в тот же тик, армия развернулась на H4 спиной к подходящему врагу и была
     *  разбита в развороте 0:12. Второй раз он сработал на 117-м посреди проигрываемого боя (падали только наши хиты) и
     *  снял бой по контакту — обмен уронами считается с обеих сторон. */
    internal const val STALL_PICKET = 4
    /** Чистый урон за окно, который считается боем: залп пикета с трёх клеток при проходе (60–180 хитов, залечены через
     *  тик) сбрасывал 300-тиковый простой, и цель-флаг пропадала посреди марша (стенд m12 spread, t=431). */
    internal const val STALL_DAMAGE = 300
    /** Масса армии — крипы не дальше этого от центра вооружённых. Оторвавшийся не решает за армию: ни точкой сбора
     *  (авангард строя выбирается ближайшим к врагу — на марше это самый оторвавшийся, и половина армии шла собираться
     *  к нему НАВСТРЕЧУ врагу, а половина — назад к посту: матч 23, t=200–211, армия разорвана на 15 клеток), ни
     *  контактом (его контакт включал ДОБИТЬ всей армии, и та входила в бой по одному — t=211–219 передний мили дрался
     *  с их строем в одиночку десять тиков). Восемь клеток — поводок (см. LEASH_RANGE), которым его и тянет назад. */
    internal const val MASS_RANGE = 8
    /** Мили в контактном бою без давления держит линию и рубит только то, что подошло на столько клеток: цель «ближайший
     *  враг в ENGAGE_RANGE» — стрелок экрана в трёх клетках — вела мили по одному в объятия мили-резерва за экраном
     *  (−720…−840 в тик, смерть за два тика; матчи 16–18, 20, 21 — пять разгромов 0:12 при 0.97). */
    internal const val MELEE_HOLD_RANGE = 2
    /** Пикет у флага: столько вооружённых врагов в KEEP_RANGE хранителя не снимают — россыпь сторожит флаг парой, и без
     *  хранителя взятый флаг отбирали за десять тиков (стенд m19 spread); армия (матч 18) — это дюжина, не пара. */
    internal const val KEEP_PICKET = 2
    /** Снятие хранителя — только когда врага нет и в этой дальности: пикет россыпи отходил за KEEP_RANGE, хранитель
     *  уходил, пикет возвращался на свободный флаг (стенд m18 spread: D5 и R3 потеряны на 815-м и 846-м). */
    internal const val KEEP_RELEASE = 20
    /** Паритетный порог при бесплодной охоте (см. STALL_TICKS): враг россыпью не дерётся и держит четыре флага, а нам
     *  0.97 запрещал четвёртый — три против четырёх до конца матча и 12:13 в тик (стенд m18/m12 spread). Против армии,
     *  которая не бьёт двадцать тиков с добычей в досягаемости, «примерно равные» — 0.93; первый же удар возвращает 0.97.
     *  ДОПУЩЕНИЕ к доктрине оператора (v14), названо в отчёте. */
    internal const val PARITY_FLOOR_STALLED = 0.93
    /** ОБЩАЯ ЦЕЛЬ ЧЕТЫРЁХ МИЛИ (v221, рычаг B пачки; разбор двух рейтинговых серий по реплеям обеих сторон).
     *  1. Замер. Во ВСЕХ шести блоб-поражениях v219–v220 через 40 тиков после контакта он не потерял ни одного
     *     стрелка и ни одного мили, мы — стрелков (первая смерть на 8–34-м тике) и мили; в четырёх из шести блоб-побед
     *     к этому сроку он потерял от двух до пяти стрелков. Хиты за первые 20 тиков при этом бывают ровными
     *     (8500 : 7493): его урон складывается в убийства — четыре мили по 240 на одном нашем стрелке в 1200, — наш
     *     размазан и залечен его тремя лекарями (216 в тик).
     *  2. Код. Удар мили (`strike`) сфокусирован — приказ командира, цель фокуса вплотную, — а НОГИ нет: вне командира
     *     каждый мили идёт к БЛИЖАЙШЕМУ допустимому врагу (`engage`, `minByOrNull { getRange }`), под командиром клетка
     *     мили считается по СУММЕ притяжения всех врагов (`attMeleeAt`), общая цель — только в замысле FOCUS. Прибор
     *     `conc` считает одних стрелков: сложены ли четыре удара в одну цель, не мерил никто (см. mconcAll).
     *  3. Правка ничего не ЗАПРЕЩАЕТ мили (этим она отличается от дважды отвергнутых ворот «мили входит парой»,
     *     USE_MELEE_PAIR_GATE) и не трогает ноги СТРЕЛКОВ (отвергнутые USE_PRESS_RING и USE_CELL_KNOWS_FOCUS): среди
     *     целей, которые мили и так разрешено брать, выбирается одна на всех — его стрелок или лекарь, ловимый и в
     *     ENGAGE_RANGE не меньше чем от двух наших мили; прежде всего липкая прежняя, затем цель фокуса. */
    /** ...и та же цель — клетке мили под командиром (v221): притяжение `attractionTo(цель пачки)` во всех замыслах, а не
     *  только в FOCUS. Экспозиция на стенде мала (командир в бою 0,4–0,9 % тиков), живьём в блоб-разгромах режим
     *  FIGHT держится десятки тиков подряд — именно там ноги мили решает командир. */
    internal const val PARITY_FLOOR_LOST = 0.75
    private const val PUSH_RELEASE_RATIO_STALEMATE = 0.95

    /** Местный бой (группа против стаи рядом) и продолжение уже начатого: вход при 0.9 — при равных силах никто
     *  не вступал в бой, и рывок врага кончался ничьёй (стенд rush). */
    internal const val LOCAL_ENTER_RATIO = 0.9

    /** Перевес врага, при котором армия отходит (и порог выхода из отхода). Решение об отходе принимается ДО
     *  контакта: при равной скорости из контакта не выйти, и 1.3 означало «в контакт при 0.77 и до конца» —
     *  матч 3, где 0.77 из четырёх дебаффов стоили всей армии. */
    private const val RETREAT_RATIO = 1.15
    private const val RETREAT_RELEASE_RATIO = 1.05

    /** Перевес врага, при котором армия ВЫХОДИТ из уже идущего боя в контакте, — много выше порога входа в отход:
     *  первая потеря в ровном бою даёт 1.18, и ОТХОД в тот же тик поставил стрелков «ждать отставших» без единого
     *  выстрела, пока мили врага резали авангард, а дальше ДОБИТЬ/ОТХОД мигали через тик — размен 1:10 при
     *  равной силе (матч 6, t=64–100). Из контакта при равной скорости всё равно не уйти; уходим, только когда
     *  бой проигран явно. */
    /** ⚠️ Снята в v217 вместе с `weakerContact`: порог «выйти из идущего боя» существовал только для него, а
     *  сам он не читался в контакте ни разу — см. разбор вакуумной охраны в `contactFight`. */

    /** Захват флага допустим, пока армия с его дебаффом НЕ СЛАБЕЕ армии врага — считая ОБЕ стороны: чужой
     *  флаг снимает дебафф с врага. При равных армиях первый флаг берёт тот, кто согласен стать слабее;
     *  прежний 0.9 «с запасом на ошибку оценки» сам был ошибкой — при 0.9 бой проигран (матч 3: три флага
     *  по 0.9 каждый дали 0.77 и разгром). Против НЕПОДВИЖНОЙ армии (PASSIVE_TICKS без единого шага —
     *  мёртвый бот матчей 1–2) порог чуть ниже: при ровно 1.0 мёртвому боту не проиграть, но и не выиграть
     *  (ни одного флага — 0:0); 0.95 пускает дешёвые флаги, а 0.85 оставляло армию при 0.83 к пробуждению
     *  «спящего» лагеря (стенд sleeper: победа держалась на удаче кайта). */
    internal const val CAPTURE_FLOOR = 1.0
    private val PUSH_DWELL = CHASE_WINDOW
    internal const val LETHAL_PENALTY = 1e6      // не запрет, а вес: если смертельны все клетки, порядок между ними цел
    /** Пара: сколько оставлено в ядре против сколько было свободных. */
    internal var symCore = 0
    internal var symFree = 0
    /** Прибор: мили-тиков, где перевес открыл ворота. Пара к edge=, который считает, где их открыть стоило. */
    internal var spotMeleeTicks = 0
    /** Вето «сперва туши очаг»: тиков с очагом и из них тех, где вето ИЗМЕНИЛО решение о постуре. */
    private var spotHoldAll = 0
    /** Пара: тиков, когда пост стал флагом, и тиков с постом вообще. */
    private var postOnFlag = 0
    private var postAll = 0
    private var postContest = 0
    internal var rotOut = 0
